prompt --application/shared_components/user_interface/lovs/ptw_authorised_persons
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(35799522908090663)
,p_lov_name=>'PTW_AUTHORISED_PERSONS'
,p_static_id=>'ptw-authorised-persons'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT',
'    u.first_name || '' '' || u.last_name     AS display_value,',
'    u.username                             AS return_value,',
'    u.mobile_no',
'FROM   ptw_pro.ptw_lv_user_roles_v  u',
'WHERE  u.role_name IN (''ADMIN'', ''AUTHORISER'')',
'AND    u.username <> ''PTW_PRO''',
'AND    u.is_active = ''Y''',
'AND    u.company_id = (',
'    CASE',
'        WHEN V(''G_OVERRIDE_COMPANY_ID'') IS NULL',
'          OR V(''G_OVERRIDE_COMPANY_ID'') = ''''',
'        THEN (SELECT company_id',
'              FROM   ptw_pro.ptw_lv_users',
'              WHERE  UPPER(username) = UPPER(:APP_USER))',
'        ELSE TO_NUMBER(V(''G_OVERRIDE_COMPANY_ID''))',
'    END',
')',
'ORDER BY display_value'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_return_column_name=>'RETURN_VALUE'
,p_display_column_name=>'DISPLAY_VALUE'
,p_default_sort_direction=>'ASC'
,p_version_scn=>'49919734007516'
,p_created_on=>wwv_flow_imp.dz('20260321130849Z')
,p_updated_on=>wwv_flow_imp.dz('20260707091753Z')
,p_created_by=>'PTW_PRO'
,p_updated_by=>'PTW_PRO'
);
end;
