,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_user_role_id NUMBER;',
'    l_username     VARCHAR2(100);',
'BEGIN',
'    l_user_role_id := TO_NUMBER(',
'                          REPLACE(:REQUEST, ''DEACTIVATE_ROLE_'', '''')',
