'           modified_date = CURRENT_TIMESTAMP,',
'           modified_by   = NVL(V(''APP_USER''), USER)',
'    WHERE  user_role_id  = l_user_role_id;',
' ',
'    COMMIT;',
'    apex_application.g_print_success_message := ''Role deactivated successfully.'';',
' ',
'EXCEPTION',
