wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(8875378004853302)
,p_validation_name=>'Check in order'
,p_static_id=>'check-in-order'
,p_validation_sequence=>50
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_unresolved NUMBER;',
'BEGIN',
'    SELECT COUNT(*)',
'    INTO   l_unresolved',
'    FROM   (SELECT 1 AS check_number FROM dual WHERE :P10_MS_CHECK1_IN_ORDER = ''N''',
'            UNION ALL',
'            SELECT 2 FROM dual WHERE :P10_MS_CHECK2_IN_ORDER = ''N''',
'            UNION ALL',
'            SELECT 3 FROM dual WHERE :P10_MS_CHECK3_IN_ORDER = ''N'') failing',
'    WHERE NOT EXISTS (',
'        SELECT 1',
'        FROM   ptw_pro.ptw_lv_monitoring_concerns mc',
'        WHERE  mc.monitoring_id     = :P10_MONITORING_ID',
'        AND    mc.check_number      = failing.check_number',
'        AND    mc.happy_to_continue IS NOT NULL',
'        AND    mc.concern_signature IS NOT NULL',
'    );',
'',
'    RETURN l_unresolved = 0;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'One or more checks marked ''not in order'' still need their concern signed off before this monitoring visit can be completed.'
,p_when_button_pressed=>wwv_flow_imp.id(40759672326498346)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
,p_created_on=>wwv_flow_imp.dz('20260720212959Z')
,p_updated_on=>wwv_flow_imp.dz('20260720212959Z')
,p_created_by=>'PTW_PRO'
,p_updated_by=>'PTW_PRO'
);
