'    reader.readAsDataURL(file);',
'}',
'',
'function p17HandleFileSelection(file) {',
'    if (!file) return;',
unistr('    // Show filename and upload button \2014 don''t upload yet'),
'    document.getElementById(''ptw-selected-file-name'').textContent   = file.name;',
