prompt --application/pages/page_00300
begin
wwv_flow_imp_page.create_page(
 p_id=>300
,p_name=>'PTW PDF Report'
,p_alias=>'PTW-PDF-REPORT'
,p_step_title=>'PTW PDF Report'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'(function () {',
'    var BINARY_ITEMS = [''P300_INCLUDE_HISTORY''];',
'',
'    var BADGES = [',
unistr('        { val: ''Y'', cls: ''binary-badge-yes'', label: ''\2713'' },'),
unistr('        { val: ''N'', cls: ''binary-badge-no'',  label: ''\2717'' }'),
'    ];',
'',
'    function initBinaryBadges() {',
'        BINARY_ITEMS.forEach(function (itemName) {',
'            var $fc = $(''#'' + itemName).closest(''.t-Form-fieldContainer'');',
'            if ($fc.length === 0) return;',
'',
'            $fc.find(''.binary-badge-row'').remove();',
'',
'            var currentVal = apex.item(itemName).getValue() || ''N'';',
'            var $row = $(''<div class="binary-badge-row"></div>'').attr(''data-item'', itemName);',
'',
'            BADGES.forEach(function (b) {',
'                $(''<span></span>'')',
'                    .addClass(''binary-badge '' + b.cls)',
'                    .toggleClass(''cm-active'', currentVal === b.val)',
'                    .attr(''data-value'', b.val)',
'                    .text(b.label)',
'                    .appendTo($row);',
'            });',
'',
'            $fc.find(''.t-Form-inputContainer'').append($row);',
'        });',
'',
'        $(''.cm-binary-item .apex-item-grid'').hide();',
'        $(''.cm-binary-item .apex-item-radio'').hide();',
'    }',
'',
'    $(document).off(''click.p300binary'').on(''click.p300binary'', ''.cm-binary-item .binary-badge'', function () {',
'        var $badge   = $(this);',
'        var $row     = $badge.closest(''.binary-badge-row'');',
'        var itemName = $row.attr(''data-item'');',
'        var val      = $badge.attr(''data-value'');',
'',
'        // Set the underlying radio value',
'        $(''input[name="'' + itemName + ''"][value="'' + val + ''"]'').prop(''checked'', true).trigger(''change'');',
'',
'        // Update badge highlight',
'        $row.find(''.binary-badge'').removeClass(''cm-active'');',
'        $badge.addClass(''cm-active'');',
'    });',
'',
'    // Run after page loads',
'    apex.jQuery(document).ready(function () {',
'        initBinaryBadges();',
'    });',
'}());'))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* =====================================================',
'   GP15 COMMERCIAL GAS SERVICE REPORT - PROFESSIONAL PDF CSS',
'   Optimized for A4 printing with efficient space usage',
'   ===================================================== */',
'',
'/* PRINT SETTINGS */',
'@media print {',
'    .t-Body-nav,',
'    .t-Header,',
'    .apex-button-group,',
'    #print-button-region,',
'    .no-print {',
'        display: none !important;',
'    }',
'    ',
'    .gp15-section {',
'        page-break-inside: avoid;',
'    }',
'    ',
'    h4 {',
'        page-break-after: avoid;',
'    }',
'    ',
'    @page {',
'        size: A4 portrait;',
'        margin: 10mm 12mm 10mm 12mm;',
'    }',
'    ',
'    body {',
'        background: white !important;',
'        -webkit-print-color-adjust: exact;',
'        print-color-adjust: exact;',
'    }',
'}',
'',
'/* MAIN CONTAINER */',
'.gp15-report-container {',
'    max-width: 210mm;',
'    margin: 0 auto;',
'    padding: 0;',
'    background: white;',
'    font-family: ''Segoe UI'', ''Arial'', sans-serif;',
'    font-size: 9pt;',
'    color: #1a1a1a;',
'    line-height: 1.35;',
'    box-shadow: 0 0 15px rgba(0,0,0,0.08);',
'}',
'',
'/* HEADER - Compact professional design */',
'.gp15-header {',
'    background: linear-gradient(135deg, #1a3a5c 0%, #2d5a8c 100%);',
'    color: white;',
'    padding: 18px 25px 16px 25px;',
'    margin-bottom: 0;',
'    border-bottom: 3px solid #0d2942;',
'}',
'',
'.gp15-header h1 {',
'    font-size: 20pt;',
'    margin: 0 0 8px 0;',
'    font-weight: 600;',
'    letter-spacing: 0.5px;',
'    text-transform: uppercase;',
'}',
'',
'.gp15-header .permit-number {',
'    font-size: 14pt;',
'    font-weight: 600;',
'    margin: 6px 0;',
'    background: rgba(255,255,255,0.15);',
'    display: inline-block;',
'    padding: 4px 14px;',
'    border-radius: 4px;',
'    border: 1px solid rgba(255,255,255,0.3);',
'}',
'',
'.gp15-header > div:last-child {',
'    display: flex;',
'    justify-content: space-between;',
'    margin-top: 10px;',
'    font-size: 9.5pt;',
'    opacity: 0.95;',
'}',
'',
'/* COMPANY LOGO */',
'.company-logo {',
'    background: rgba(255,255,255,0.95);',
'    padding: 8px 12px;',
'    border-radius: 4px;',
'    display: inline-flex;',
'    align-items: center;',
'    justify-content: center;',
'    min-height: 50px;',
'    min-width: 120px;',
'    box-shadow: 0 2px 6px rgba(0,0,0,0.15);',
'    margin-bottom: 10px;',
'}',
'',
'.company-logo img {',
'    max-height: 50px;',
'    max-width: 180px;',
'    display: block;',
'}',
'',
'.company-logo:empty::before {',
'    content: ''YOUR COMPANY'';',
'    color: #1a3a5c;',
'    font-weight: 700;',
'    font-size: 12pt;',
'    letter-spacing: 0.8px;',
'}',
'',
'/* SECTIONS - Compact with clear borders */',
'.gp15-section {',
'    margin: 0;',
'    background: white;',
'    border: 1px solid #c8d1db;',
'    border-top: none;',
'}',
'',
'.gp15-section:first-of-type {',
'    border-top: 1px solid #c8d1db;',
'}',
'',
'.gp15-section-title {',
'    background: linear-gradient(to bottom, #e8ecf1 0%, #dce3ea 100%);',
'    padding: 8px 16px;',
'    font-weight: 700;',
'    font-size: 10pt;',
'    color: #1a3a5c;',
'    border-bottom: 2px solid #b0bcc9;',
'    text-transform: uppercase;',
'    letter-spacing: 0.5px;',
'}',
'',
'/* DATA ROWS - Clean and efficient */',
'.gp15-row {',
'    display: flex;',
'    padding: 6px 16px;',
'    border-bottom: 1px solid #e8ecf1;',
'    align-items: center;',
'}',
'',
'.gp15-row:last-child {',
'    border-bottom: none;',
'}',
'',
'.gp15-row:nth-child(even) {',
'    background: #f8f9fb;',
'}',
'',
'.gp15-label {',
'    font-weight: 600;',
'    width: 38%;',
'    padding-right: 12px;',
'    color: #2c3e50;',
'    font-size: 9pt;',
'    flex-shrink: 0;',
'}',
'',
'.gp15-value {',
'    width: 62%;',
'    color: #1a1a1a;',
'    font-size: 9pt;',
'    word-wrap: break-word;',
'}',
'',
'/* TABLES - Professional grid design */',
'.gp15-table {',
'    width: 100%;',
'    border-collapse: collapse;',
'    margin: 0;',
'    font-size: 8.5pt;',
'    background: white;',
'}',
'',
'.gp15-table th {',
'    background: linear-gradient(to bottom, #2c3e50 0%, #1a2836 100%);',
'    color: white;',
'    padding: 7px 6px;',
'    font-weight: 600;',
'    text-align: left;',
'    font-size: 8.5pt;',
'    text-transform: uppercase;',
'    letter-spacing: 0.3px;',
'    border: 1px solid #1a2836;',
'}',
'',
'.gp15-table td {',
'    border: 1px solid #c8d1db;',
'    padding: 6px 6px;',
'    color: #1a1a1a;',
'    vertical-align: middle;',
'}',
'',
'.gp15-table tr:nth-child(even) {',
'    background: #f8f9fb;',
'}',
'',
'.gp15-table td strong {',
'    color: #1a3a5c;',
'    font-weight: 600;',
'}',
'',
'/* Compact table for appliance details */',
'.gp15-table.compact th,',
'.gp15-table.compact td {',
'    padding: 5px 4px;',
'    font-size: 8pt;',
'}',
'',
'/* SUBSECTION HEADERS */',
'h4 {',
'    color: #1a3a5c;',
'    font-size: 9.5pt;',
'    font-weight: 600;',
'    margin: 12px 16px 8px 16px;',
'    padding-bottom: 4px;',
'    border-bottom: 2px solid #3498db;',
'    text-transform: uppercase;',
'    letter-spacing: 0.3px;',
'}',
'',
'/* SIGNATURE BOXES - Clear professional display */',
'.signature-box {',
'    border: 2px solid #b0bcc9;',
'    min-height: 65px;',
'    height: 65px;',
'    padding: 8px;',
'    margin-top: 6px;',
'    background: #fafbfc;',
'    border-radius: 3px;',
'    display: flex;',
'    align-items: center;',
'    justify-content: center;',
'    overflow: hidden;',
'}',
'',
'.signature-image {',
'    max-width: 100%;',
'    max-height: 55px;',
'    display: block;',
'    object-fit: contain;',
'}',
'',
'.signature-box p {',
'    margin: 0;',
'    color: #7f8c9a;',
'    font-style: italic;',
'    font-size: 8.5pt;',
'    text-align: center;',
'}',
'',
'/* SIGNATURE SECTION - Two column grid */',
'.signature-grid {',
'    display: grid;',
'    grid-template-columns: 1fr 1fr;',
'    gap: 16px;',
'    padding: 12px 16px;',
'}',
'',
'.signature-block {',
'    border: 1px solid #dce3ea;',
'    padding: 10px;',
'    background: white;',
'    border-radius: 3px;',
'}',
'',
'.signature-block strong {',
'    display: block;',
'    margin-bottom: 6px;',
'    color: #1a3a5c;',
'    font-size: 9.5pt;',
'}',
'',
'.signature-details {',
'    margin-top: 6px;',
'    font-size: 8.5pt;',
'    line-height: 1.5;',
'    color: #2c3e50;',
'}',
'',
'.signature-details strong {',
'    display: inline;',
'    font-size: 8.5pt;',
'    font-weight: 600;',
'}',
'',
'/* DECLARATION BOX - Prominent notice */',
'.declaration-box {',
'    background: linear-gradient(135deg, #fff9e6 0%, #fff3cc 100%);',
'    border: 2px solid #f5c563;',
'    border-left: 4px solid #e6a023;',
'    padding: 14px 16px;',
'    margin: 12px 16px;',
'    font-weight: 500;',
'    border-radius: 3px;',
'    box-shadow: 0 2px 4px rgba(230, 160, 35, 0.15);',
'}',
'',
'.declaration-box strong {',
'    display: block;',
'    font-size: 10pt;',
'    color: #7d5d1f;',
'    margin-bottom: 8px;',
'    text-transform: uppercase;',
'    letter-spacing: 0.4px;',
'}',
'',
'.declaration-box p {',
'    color: #7d5d1f;',
'    margin: 0;',
'    line-height: 1.5;',
'    font-size: 9pt;',
'}',
'',
'/* GRID LAYOUTS - Compact spacing */',
'.gp15-grid-2 {',
'    display: grid;',
'    grid-template-columns: 1fr 1fr;',
'    gap: 10px;',
'    padding: 10px 16px;',
'}',
'',
'.gp15-grid-3 {',
'    display: grid;',
'    grid-template-columns: 1fr 1fr 1fr;',
'    gap: 10px;',
'    padding: 10px 16px;',
'}',
'',
'/* FOOTER - Minimal professional */',
'.gp15-footer {',
'    text-align: center;',
'    margin-top: 0;',
'    padding: 12px 16px;',
'    background: #f0f3f6;',
'    border-top: 2px solid #b0bcc9;',
'    font-size: 7.5pt;',
'    color: #6c757d;',
'    line-height: 1.4;',
'}',
'',
'.gp15-footer strong {',
'    color: #495057;',
'    font-weight: 600;',
'}',
'',
'/* STATUS BADGES */',
'.status-badge {',
'    display: inline-block;',
'    padding: 3px 10px;',
'    border-radius: 10px;',
'    font-size: 8pt;',
'    font-weight: 600;',
